import { Drawing } from "../drawing/drawing";
import { CoordinateStore } from "../store";
export class BaseTrack extends HTMLElement {
    constructor() {
        super();
        Object.defineProperty(this, "name", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "template", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "shadow", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "canvas", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "ctx", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "label", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "width", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "store", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "isPanning", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "mouseDownPos", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        this.template = document.createElement("template");
        this.shadow = this.attachShadow({ mode: "open" });
        this.name = "base";
        this.label = "";
        this.isPanning = false;
        this.mouseDownPos = [0, 0];
    }
    /*----------------------------------------|
    |                 GETTERS                 |
    |----------------------------------------*/
    getStoreId() {
        return this.getAttribute("store");
    }
    getCanvasWidth() {
        return this.canvas.getBoundingClientRect().width;
    }
    getCanvasHeight() {
        return this.canvas.getBoundingClientRect().height;
    }
    /*----------------------------------------|
    |                 SETTERS                 |
    |----------------------------------------*/
    setCursorStyle(style) {
        this.canvas.style.cursor = style;
    }
    /*----------------------------------------|
    |                LIFECYCLE                |
    |----------------------------------------*/
    connectedCallback() {
        this.render();
        this.initializeTrack();
    }
    render() {
        this.template.innerHTML = this.html();
        this.shadow.appendChild(this.template.content.cloneNode(true));
        this.canvas = this.shadowRoot.querySelector("canvas");
        this.ctx = this.canvas.getContext("2d");
        this.store = CoordinateStore.getInstance(this.getStoreId());
        this.addEventListeners();
        this.redraw();
    }
    initializeTrack() {
        this.store.registerListener(this);
    }
    addEventListeners() {
        this.canvas.addEventListener("mouseup", this.mouseUpHandler.bind(this));
        this.canvas.addEventListener("mouseout", this.mouseOutHandler.bind(this));
        this.canvas.addEventListener("mousedown", this.mouseDownHandler.bind(this));
        this.canvas.addEventListener("mousemove", this.mouseMoveHandler.bind(this));
    }
    /*----------------------------------------|
    |                 DRAWING                 |
    |----------------------------------------*/
    update() { }
    redraw() { }
    refreshCanvas() {
        this.clearCanvas();
        Drawing.adjustforPixelRatios(window, this.canvas, this.ctx);
    }
    clearCanvas(opacity = 1) {
        this.ctx.fillStyle = "white";
        this.ctx.globalAlpha = opacity;
        this.ctx.fillRect(0, 0, this.getCanvasWidth(), this.getCanvasHeight());
        this.ctx.globalAlpha = 1;
    }
    drawStyledText(ctx, text, x, y, normalFont, italicFont) {
        const parts = text.split('*');
        let currentX = x;
        for (let i = 0; i < parts.length; i++) {
            const part = parts[i];
            if (part) { // Skip empty parts
                ctx.font = (i % 2 === 0) ? normalFont : italicFont;
                ctx.fillText(part, currentX, y);
                currentX += ctx.measureText(part).width;
            }
        }
    }
    /*----------------------------------------|
    |               HTML & CSS                |
    |----------------------------------------*/
    html() {
        return `
            <style> ${this.css()} </style>
            <div id="track-container">
                <div id="track-label">${this.label || '&nbsp;'}</div>
                <div id="canvas-container">
                    <canvas id='${this.name}-track'></canvas>
                </div>
            </div>
        `;
    }
    css() {
        return `
            :host {
                display: block;
                height: 100%;
                width: fit-content;
            }

            #track-container, #canvas-container, #track-label {
                box-sizing: border-box;
            }

            #track-container {
                display: flex;
                flex-direction: column;
                width: ${this.width}px;
                height: 100%;
            }

            #track-label {
                height: 30px;
                line-height: 30px;
                text-align: center;
                background: #eee;
                font-size: 14px;
                font-weight: bold;
            }

            #canvas-container {
                display: block;
                width: ${this.width}px;
                height: calc(100% - 30px);
            }

            #track-label, #canvas-container {
                border: 1px solid black;
            }
            
            canvas {
                width: 100%;
                height: 100%;
                display: block;
            }
        `;
    }
    /*----------------------------------------|
    |                HANDLERS                 |
    |----------------------------------------*/
    mouseDownHandler(event) {
        event.preventDefault();
        this.mouseDownPos = [event.offsetX, event.offsetY];
        this.isPanning = true;
    }
    mouseMoveHandler(event) {
        if (this.isPanning)
            this.handlePanning(event);
        else
            this.handleMouseNotOverFeature(event);
    }
    mouseOutHandler(event) {
        if (this.isPanning) {
            this.isPanning = false;
            this.setCursorStyle("grab");
        }
    }
    mouseUpHandler(event) {
        if (this.isPanning) {
            this.isPanning = false;
            this.setCursorStyle("grab");
        }
    }
    handlePanning(event) {
        this.setCursorStyle("grabbing");
        this.scrollVertically(event);
    }
    handleMouseNotOverFeature(event) {
        this.setCursorStyle("grab");
    }
    scrollVertically(event) {
        this.store.scroll(-event.movementY);
    }
}
